#!/usr/bin/env bash
# Remote half of eval:tb21:aws. The local orchestrator uploads this file and a
# non-secret config; provider credentials arrive through Secrets Manager.
set -Eeuo pipefail

[ $# -eq 1 ] || { echo "usage: aws_runner.sh CONFIG" >&2; exit 2; }
# shellcheck disable=SC1090 # generated by the local orchestrator
source "$1"
export RUN_ID COMMIT REGION BUCKET SECRET_ARN MODEL_ID CONCURRENCY PASSES
export EXPECTED_TASKS RUN_MODE MAX_TOPUP_ROUNDS INSTANCE_TYPE INSTANCE_ID AMI_ID AVAILABILITY_ZONE
export CONTROLLER_COMMIT REMOTE_RUNNER_SHA256 MERGE_HELPER_SHA256 SMOKE_TASKSET_SHA256

ROOT=/opt/stella-tb21
REPO=$ROOT/stella
JOURNAL=$ROOT/remote-journal.ndjson
STATUS=$ROOT/status.json
FINAL_PHASE=""
export HOME=/root
export AWS_DEFAULT_REGION=$REGION
export PATH="/root/.local/bin:/usr/local/bin:$PATH"

journal() {
  phase=$1
  detail=${2:-}
  python3 - "$JOURNAL" "$STATUS" "$RUN_ID" "$COMMIT" "$phase" "$detail" <<'PY'
import datetime, json, pathlib, sys
journal, status, run_id, commit, phase, detail = sys.argv[1:]
record = {
    "at": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
    "run_id": run_id,
    "commit": commit,
    "phase": phase,
}
if detail:
    record["detail"] = detail
with pathlib.Path(journal).open("a") as stream:
    stream.write(json.dumps(record, sort_keys=True) + "\n")
pathlib.Path(status).write_text(json.dumps(record, sort_keys=True) + "\n")
PY
  aws s3 cp "$JOURNAL" "s3://$BUCKET/journal/remote.ndjson" --only-show-errors
  aws s3 cp "$STATUS" "s3://$BUCKET/status.json" --only-show-errors
}

finish() {
  code=$?
  set +e
  if [ -z "$FINAL_PHASE" ]; then
    journal "failed" "exit=$code line=${BASH_LINENO[0]:-unknown}"
  fi
  rm -f "$REPO/.env" "$ROOT/provider.json"
  rm -rf "$REPO/dist/evals" "$ROOT/jobs" "$ROOT/merged" "$ROOT/redacted"
  # run-instances sets shutdown behavior to terminate. This is the backstop if
  # the local controller disconnects after starting the SSM command.
  shutdown -h now >/dev/null 2>&1 || true
  trap - EXIT
  exit "$code"
}
trap finish EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM

mkdir -p "$ROOT" "$ROOT/logs" "$ROOT/jobs"
journal preparing-host
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq
apt-get install -y -qq ca-certificates curl docker.io docker-compose-v2 git jq python3 unzip
systemctl enable --now docker
docker compose version >/dev/null
id -u stella-eval >/dev/null 2>&1 || useradd --create-home --shell /bin/bash stella-eval
usermod -aG docker stella-eval
EVAL_HOME=/home/stella-eval

if [ ! -x /root/.local/bin/mise ]; then
  curl -fsSL https://mise.run | sh
fi
install -m 0755 /root/.local/bin/mise /usr/local/bin/mise

# Source must be checked out under the normal repository mode. A global 077
# umask made bundled skills 0600 in the first attempt and wasted the host.
umask 022
journal fetching-source
aws s3 cp "s3://$BUCKET/input/stella.bundle" "$ROOT/stella.bundle" --only-show-errors
rm -rf "$REPO"
git clone --quiet "$ROOT/stella.bundle" "$REPO"
rm -f "$ROOT/stella.bundle"
cd "$REPO"
git checkout --quiet --detach "$COMMIT"
[ "$(git rev-parse HEAD)" = "$COMMIT" ]
if find plugins/core/skills -type f ! -perm -004 -print -quit | grep -q .; then
  echo "bundled skill is not world-readable after checkout" >&2
  exit 1
fi

# Restrict only the credential payload, never the source checkout.
umask 077
aws secretsmanager get-secret-value --secret-id "$SECRET_ARN" --query SecretString --output text > "$ROOT/provider.json"
python3 - "$ROOT/provider.json" "$REPO/.env" <<'PY'
import json, pathlib, shlex, sys
values = json.loads(pathlib.Path(sys.argv[1]).read_text())
required = ("OPENAI_BASE_URL", "OPENAI_API_KEY", "OPENAI_MODEL")
missing = [name for name in required if not values.get(name)]
if missing:
    raise SystemExit("provider secret lacks: " + ", ".join(missing))
pathlib.Path(sys.argv[2]).write_text("".join(f"{name}={shlex.quote(values[name])}\n" for name in required))
PY
chmod 600 "$REPO/.env"
chown -R stella-eval:stella-eval "$REPO" "$ROOT/logs" "$ROOT/jobs"

as_eval() {
  # shellcheck disable=SC2016 # expanded by the child bash after positional args are installed
  runuser -u stella-eval -- env HOME="$EVAL_HOME" PATH=/usr/local/bin:/usr/bin:/bin \
    bash -c 'cd "$1"; shift; set -a; source .env; set +a; exec "$@"' _ "$REPO" "$@"
}

set -a
# shellcheck disable=SC1091 # private file generated immediately above
source "$REPO/.env"
set +a
rm -f "$ROOT/provider.json"
[ "$OPENAI_MODEL" = "$MODEL_ID" ] || { echo "configured model differs from requested model" >&2; exit 1; }
export STELLA_EVAL_MODEL_ID=$OPENAI_MODEL
unset OTEL_STELLA_RECORD_TOOL_IO
umask 022

journal installing-toolchain
as_eval mise trust --yes
as_eval mise install
# uv is intentionally not a repository-wide tool. Register the pin in this
# disposable worker's global mise config so nested `mise run` tasks retain it.
as_eval mise use --global uv@0.12.6
as_eval mise exec -- uv --version | grep -q '^uv 0\.12\.6 '
as_eval mise run setup
[ -z "$(git status --porcelain)" ] || { echo "setup changed tracked source" >&2; git status --short; exit 1; }

cat >/etc/docker/daemon.json <<'JSON'
{
  "default-address-pools": [
    { "base": "10.201.0.0/16", "size": 24 },
    { "base": "10.202.0.0/16", "size": 24 }
  ]
}
JSON
systemctl restart docker
until docker info >/dev/null 2>&1; do sleep 1; done
[ "$(df --output=avail -B1 / | tail -1)" -ge 107374182400 ] || { echo "less than 100 GiB free before evaluation" >&2; exit 1; }

journal remote-preflight
if [ "$RUN_MODE" = smoke ]; then
  as_eval mise run eval:loop -- --plan -c "$ROOT/aws-smoke.yaml" -n "$CONCURRENCY" > "$ROOT/logs/plan.log"
else
  as_eval mise run eval:loop -- --plan -d terminal-bench/terminal-bench-2-1 -k 1 -n "$CONCURRENCY" > "$ROOT/logs/plan.log"
fi
grep -q 'plan only, nothing is executed' "$ROOT/logs/plan.log"
grep -q 'OPENAI_BASE_URL (set' "$ROOT/logs/plan.log"
grep -q 'OPENAI_API_KEY (set)' "$ROOT/logs/plan.log"

safe_testbed_diagnostic() {
  testbed_log=$(find "$REPO/dist/evals/runs" -type f -name testbed.log 2>/dev/null | sort | tail -1)
  [ -n "$testbed_log" ] || return 0
  python3 - "$testbed_log" <<'PY'
import pathlib, re, sys

lines = pathlib.Path(sys.argv[1]).read_text(errors="replace").splitlines()
interesting = re.compile(
    r"error|fatal|panic|failed|unsupported|permission denied|no such file|exited|runtime|postgres",
    re.IGNORECASE,
)
secret = re.compile(
    r"(?i)(authorization|api[_-]?key|token|secret|password)(?:\s*[:=]\s*|\s+)[^\s,;]+"
)
long_value = re.compile(r"(?<![0-9a-f])[A-Za-z0-9_+/=-]{24,}(?![0-9a-f])", re.IGNORECASE)
url = re.compile(r"https?://[^\s]+", re.IGNORECASE)
selected = []
for line in lines:
    if not interesting.search(line):
        continue
    line = secret.sub(r"\1=[REDACTED]", line)
    line = url.sub("[URL]", line)
    line = long_value.sub("[REDACTED]", line)
    selected.append(line[:240])
print(" | ".join(selected[-3:]))
PY
}

safe_process_error() {
  python3 - "$1" <<'PY'
import pathlib, re, sys

text = pathlib.Path(sys.argv[1]).read_text(errors="replace")
error_types = sorted(set(re.findall(r"\b[A-Za-z][A-Za-z0-9_.]*(?:Error|Exception)\b", text)))
lower = text.lower()
checks = {
    "permission_denied": "permission denied" in lower,
    "no_such_file": "no such file" in lower,
    "not_found": "not found" in lower,
    "invalid": "invalid" in lower,
    "missing": "missing" in lower,
    "unsupported": "unsupported" in lower,
}
categories = sorted(name for name, matched in checks.items() if matched)
print(f"types={','.join(error_types) or 'none'} categories={','.join(categories) or 'unclassified'}")
PY
}

run_eval() {
  group=$1
  shift
  log=$ROOT/logs/$group.log
  mkdir -p "$(dirname "$log")"
  [ "$(awk '/MemAvailable:/ {print $2}' /proc/meminfo)" -ge 16777216 ] || {
    echo "less than 16 GiB available before $group" >&2
    exit 1
  }
  [ "$(df --output=avail -B1 /var/lib/docker | tail -1)" -ge 107374182400 ] || {
    echo "less than 100 GiB free before $group" >&2
    exit 1
  }
  [ -z "$(docker ps -q)" ] || { echo "container from an earlier pass is still running" >&2; exit 1; }
  journal "$group-running"
  before=$(find "$REPO/dist/evals/jobs" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | sort || true)
  set +e
  as_eval mise run eval:loop -- "$@" >"$log" 2>&1
  eval_status=$?
  set -e
  if [ "$eval_status" -ne 0 ]; then
    # loop.sh promises that its own eval:loop-prefixed errors never contain
    # credential values. Do not upload arbitrary Harbor output: tasks may print
    # synthetic secrets even when the run fails.
    diagnostic=$(grep '^eval:loop:' "$log" | tail -3 | tr '\n' ';' || true)
    [ -n "$diagnostic" ] || diagnostic=no-safe-diagnostic
    if printf '%s' "$diagnostic" | grep -q 'testbed exited early'; then
      testbed_diagnostic=$(safe_testbed_diagnostic)
      [ -z "$testbed_diagnostic" ] || diagnostic="$diagnostic testbed=$testbed_diagnostic"
    fi
    journal "$group-failed" "exit=$eval_status diagnostic=$diagnostic"
    return "$eval_status"
  fi
  [ -z "$(docker ps -q)" ] || { echo "eval left a task container running after $group" >&2; exit 1; }
  [ -z "$(pgrep -x stellad || true)" ] || { echo "eval left stellad running after $group" >&2; exit 1; }
  [ -z "$(pgrep -x postgres || true)" ] || { echo "eval left PostgreSQL running after $group" >&2; exit 1; }
  job=$(sed -n 's/^[[:space:]]*job: //p' "$log" | tail -1)
  [ -n "$job" ] && [ -d "$job" ]
  if [ -n "$before" ] && printf '%s\n' "$before" | grep -Fqx "$job"; then
    echo "eval resolved to a pre-existing job: $job" >&2
    exit 1
  fi
  mkdir -p "$ROOT/jobs/$group"
  mv "$job" "$ROOT/jobs/$group/"
  [ ! -f "$job.manifest.json" ] || mv "$job.manifest.json" "$ROOT/jobs/$group/"
  journal "$group-complete"
}

# The full run warms all 89 images and proves scoreable evidence before buying
# 445 reportable attempts. Smoke mode is itself the preflight and skips this
# additional full-dataset expense.
if [ "$RUN_MODE" = full ]; then
  run_eval warmup -d terminal-bench/terminal-bench-2-1 -k 1 -n "$CONCURRENCY"
  WARMUP=$(python3 "$ROOT/aws_merge.py" "$ROOT/jobs/warmup" --k 1)
  python3 - "$WARMUP" <<'PY'
import json, sys
state = json.loads(sys.argv[1])
if state["tasks"] != 89 or state["missing"]:
    raise SystemExit(f"warm-up was not complete and scoreable: {state}")
PY
  rm -rf "$ROOT/jobs/warmup"
  journal warmup-discarded
fi

# Each logical pass reaches one scoreable trial per task before the next pass
# begins. This fixes the evidence order up front: main pass, then its top-ups,
# then the next pass. Reward values never participate in the decision.
pass=1
while [ "$pass" -le "$PASSES" ]; do
  pass_name=pass-$(printf '%02d' "$pass")
  if [ "$RUN_MODE" = smoke ]; then
    run_eval "$pass_name/00-main" -c "$ROOT/aws-smoke.yaml" -n "$CONCURRENCY"
  else
    run_eval "$pass_name/00-main" -d terminal-bench/terminal-bench-2-1 -k 1 -n "$CONCURRENCY"
  fi
  round=1
  while :; do
    INVENTORY=$(python3 "$ROOT/aws_merge.py" "$ROOT/jobs/$pass_name" --k 1)
    inventory_detail=$(python3 - "$INVENTORY" <<'PY'
import json, sys
state = json.loads(sys.argv[1])
print(
    f"tasks={state['tasks']} trials={state['trials']} scoreable={state['scoreable']} "
    f"invalid={state['invalid']} reasons={json.dumps(state['invalid_reasons'], sort_keys=True)} "
    f"exceptions={json.dumps(state['exception_types'], sort_keys=True)} "
    f"categories={json.dumps(state['exception_categories'], sort_keys=True)} "
    f"signatures={json.dumps(state['exception_signatures'], sort_keys=True)} "
    f"attributes={json.dumps(state['exception_attributes'], sort_keys=True)} "
    f"receivers={json.dumps(state['exception_receivers'], sort_keys=True)} "
    f"names={','.join(state['task_names'])}"
)
PY
)
    journal "$pass_name-inventory" "$inventory_detail"
    observed_tasks=$(python3 -c 'import json,sys; print(json.loads(sys.argv[1])["tasks"])' "$INVENTORY")
    [ "$observed_tasks" -eq "$EXPECTED_TASKS" ] || {
      echo "$pass_name observed $observed_tasks tasks, expected $EXPECTED_TASKS" >&2
      exit 1
    }
    if [ "$RUN_MODE" = smoke ]; then
      systematic_failure=$(python3 - "$INVENTORY" <<'PY'
import json, sys
state = json.loads(sys.argv[1])
missing_adapter = state["invalid_reasons"] == {"missing_adapter_result": state["trials"]}
same_attribute_error = (
    state["trials"] > 0
    and state["scoreable"] == 0
    and state["invalid_reasons"] == {"adapter_invalid": state["trials"]}
    and state["exception_types"] == {"AttributeError": state["trials"]}
    and len(state["exception_attributes"]) == 1
)
print(int(missing_adapter or same_attribute_error))
PY
)
      [ "$systematic_failure" -eq 0 ] || {
        echo "$pass_name produced one shared adapter startup failure; refusing redundant top-ups" >&2
        exit 1
      }
    fi
    MISSING=$(python3 - "$INVENTORY" <<'PY'
import json, sys
for task, count in sorted(json.loads(sys.argv[1])["missing"].items()):
    print(f"{task}\t{count}")
PY
)
    [ -n "$MISSING" ] || break
    [ "$round" -le "$MAX_TOPUP_ROUNDS" ] || {
      echo "$pass_name still lacks scoreable evidence after $MAX_TOPUP_ROUNDS top-up rounds" >&2
      exit 1
    }
    journal "$pass_name-topup-$round" "missing=$(printf '%s\n' "$MISSING" | wc -l | tr -d ' ')"
    while IFS=$'\t' read -r task count; do
      [ -n "$task" ] || continue
      run_eval "$pass_name/topup-$(printf '%02d' "$round")-$task" \
        -i "terminal-bench/$task" -k "$count" -n "$count"
    done <<< "$MISSING"
    round=$((round + 1))
  done
  journal "$pass_name-scoreable"
  pass=$((pass + 1))
done

journal selecting-evidence
python3 "$ROOT/aws_merge.py" "$ROOT/jobs" --k "$PASSES" \
  --expected-tasks "$EXPECTED_TASKS" --concurrency "$CONCURRENCY" \
  --output "$ROOT/merged" > "$ROOT/selection.json"
# copytree preserves restrictive trial modes while root owns the copies.
# Return the selected evidence to the unprivileged reporter before reading it.
chown -R stella-eval:stella-eval "$ROOT/merged"
journal evidence-selected
set +e
as_eval mise exec -- uv run --project test/evals/harbor python -m stella_harbor.report \
  "$ROOT/merged" > "$ROOT/report.txt" 2> "$ROOT/logs/text-report.err"
report_status=$?
set -e
if [ "$report_status" -ne 0 ]; then
  journal text-report-failed "exit=$report_status $(safe_process_error "$ROOT/logs/text-report.err")"
  exit "$report_status"
fi
rm -f "$ROOT/logs/text-report.err"
journal text-report-complete
touch "$ROOT/report.html"
chown stella-eval:stella-eval "$ROOT/report.html"
as_eval mise exec -- uv run --project test/evals/harbor python -m stella_harbor.report \
  "$ROOT/merged" --html "$ROOT/report.html" >/dev/null
journal html-report-complete
mkdir -p "$ROOT/redacted"
chown stella-eval:stella-eval "$ROOT/redacted"
as_eval mise exec -- uv run --project test/evals/harbor python -m stella_harbor.archive \
  "$ROOT/merged" --include-trajectories --output "$ROOT/redacted" > "$ROOT/archive-summary.txt"
journal redacted-archive-complete

python3 - "$ROOT/run-metadata.json" <<'PY'
import datetime, json, os, pathlib, platform, subprocess

def out(*args: str) -> str:
    return subprocess.run(args, text=True, capture_output=True, check=True).stdout.strip()

metadata = {
    "run_id": os.environ["RUN_ID"],
    "candidate_commit": os.environ["COMMIT"],
    "controller_commit": os.environ["CONTROLLER_COMMIT"],
    "remote_runner_sha256": os.environ["REMOTE_RUNNER_SHA256"],
    "merge_helper_sha256": os.environ["MERGE_HELPER_SHA256"],
    "smoke_taskset_sha256": os.environ["SMOKE_TASKSET_SHA256"],
    "dataset": "terminal-bench/terminal-bench-2-1",
    "dataset_sha256": "7d7bdc1cbedad549fc1140404bd4dc45e5fd0ea7c4186773687d177ad3a0699a",
    "model": "gateway/" + os.environ["MODEL_ID"],
    "run_mode": os.environ["RUN_MODE"],
    "tasks": int(os.environ["EXPECTED_TASKS"]),
    "attempts_per_task": int(os.environ["PASSES"]),
    "concurrency": int(os.environ["CONCURRENCY"]),
    "agent_timeout_multiplier": 1.0,
    "tool_treatment": "Code Mode all registered Stella capabilities; view_image,vllm excluded; bridge-attributable bash execution",
    "otel_tool_io_recording": False,
    "host": {
        "instance_type": os.environ["INSTANCE_TYPE"],
        "instance_id": os.environ["INSTANCE_ID"],
        "ami_id": os.environ["AMI_ID"],
        "region": os.environ["REGION"],
        "availability_zone": os.environ["AVAILABILITY_ZONE"],
        "kernel": platform.release(),
        "architecture": platform.machine(),
        "vcpus": int(out("nproc")),
        "memory": out("grep", "MemTotal", "/proc/meminfo"),
    },
    "completed_at": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
}
pathlib.Path("/opt/stella-tb21/run-metadata.json").write_text(json.dumps(metadata, indent=2) + "\n")
PY
journal metadata-complete

mkdir -p "$ROOT/artifacts"
tar -C "$ROOT/redacted" -czf "$ROOT/artifacts/results-redacted.tgz" .
cp "$ROOT/report.txt" "$ROOT/report.html" "$ROOT/run-metadata.json" \
  "$ROOT/selection.json" "$ROOT/archive-summary.txt" "$JOURNAL" "$ROOT/artifacts/"
(
  cd "$ROOT/artifacts"
  sha256sum results-redacted.tgz report.txt report.html run-metadata.json \
    selection.json archive-summary.txt remote-journal.ndjson > SHA256SUMS
)
aws s3 sync "$ROOT/artifacts" "s3://$BUCKET/artifacts" --only-show-errors
journal artifacts-uploaded
FINAL_PHASE=complete
journal complete
